INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2388664, 327137, 56454, '<td valign="top">Nice shot.  Nice composition and great lighting.  I can''t figure out how the ladder shadows were done.  I like that the predominance of color is in the man.</td>', 'Nice shot.  Nice composition and great lighting.  I can''t figure out how the ladder shadows were done.  I like that the predominance of color is in the man.', '2006-05-07 01:47:30.000000', NULL, 1),
(2388667, 328045, 56454, '<td valign="top">Nice subtely.  I didn''t catch it at first glance.  I like the far edge of the book out of focus but would have preferred the close edge to be sharp.  This is picky (and isn''t influencing my score) but I think it would be better without the ring on the finger.<br/>One of my favorites.</td>', 'Nice subtely.  I didn''t catch it at first glance.  I like the far edge of the book out of focus but would have preferred the close edge to be sharp.  This is picky (and isn''t influencing my score) but I think it would be better without the ring on the finger.One of my favorites.', '2006-05-07 01:47:44.000000', NULL, 1),
(2388668, 327059, 56454, '<td valign="top">Nice emotion and lighting.  I don''t know if it was planned but her warm jacket reinforces the "cold feelings" of a break up. Curious if you took one with the subjects facing away from each other and how that looked.</td>', 'Nice emotion and lighting.  I don''t know if it was planned but her warm jacket reinforces the "cold feelings" of a break up. Curious if you took one with the subjects facing away from each other and how that looked.', '2006-05-07 01:47:47.000000', NULL, 1),
