INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2396727, 328854, 45004, '<td valign="top">Creative lighting. I like the back lit bullet.</td>', 'Creative lighting. I like the back lit bullet.', '2006-05-09 10:59:57.000000', NULL, 1),
(2396730, 327053, 47534, '<td valign="top">Terrific use of contrast, DOF, and imagery...</td>', 'Terrific use of contrast, DOF, and imagery...', '2006-05-09 11:01:22.000000', NULL, 1),
(2396734, 329337, 47534, '<td valign="top">You could have very easily found a bunch of gigantic machinery, but I really like that you pictured a large group of hard working people instead.  It provides an amazingly powerful feel to the picture that would be sorely lacking with the impersonality of earth-moving equipment.<br/> <br/>Great job!</td>', 'You could have very easily found a bunch of gigantic machinery, but I really like that you pictured a large group of hard working people instead.  It provides an amazingly powerful feel to the picture that would be sorely lacking with the impersonality of earth-moving equipment. Great job!', '2006-05-09 11:04:52.000000', NULL, 1),
(2396736, 328861, 47534, '<td valign="top">Very well composed!</td>', 'Very well composed!', '2006-05-09 11:05:32.000000', NULL, 1),
(2396738, 328716, 58673, '<td valign="top">Looks good but it seems a little out of focus. could this be do to .jpg compression?<br/> <br/>cheers</td>', 'Looks good but it seems a little out of focus. could this be do to .jpg compression? cheers', '2006-05-09 11:06:24.000000', NULL, 1),
(2396742, 328045, 47534, '<td valign="top">Great job!  I like the way this makes the viewer have to pay a little extra attention, how you expect to see bits of serious words but find only imagery that takes you immediately back to childhood.<br/> <br/>Great job!!!!!!!!!!</td>', 'Great job!  I like the way this makes the viewer have to pay a little extra attention, how you expect to see bits of serious words but find only imagery that takes you immediately back to childhood. Great job!!!!!!!!!!', '2006-05-09 11:07:57.000000', NULL, 1),
(2396743, 329087, 58673, '<td valign="top">not sure how this fits the saying<br/>good luck</td>', 'not sure how this fits the sayinggood luck', '2006-05-09 11:08:02.000000', NULL, 1),
(2396748, 328819, 16402, '<td valign="top">I''ve never heard that one, but I''ll give you the benefit if the doubt that it might be "well-known" or "often heard" somewhere.</td>', 'I''ve never heard that one, but I''ll give you the benefit if the doubt that it might be "well-known" or "often heard" somewhere.', '2006-05-09 11:09:00.000000', NULL, 1),
