(2396751, 327531, 47534, '<td valign="top">beautiful picture...</td>', 'beautiful picture...', '2006-05-09 11:09:28.000000', NULL, 1),
(2396753, 328143, 45004, '<td valign="top">Like the concept, but would have liked the background to be cleaner (no signs, no birdhouse, no top of lamp in forground)).</td>', 'Like the concept, but would have liked the background to be cleaner (no signs, no birdhouse, no top of lamp in forground)).', '2006-05-09 11:09:44.000000', NULL, 1),
