(2396812, 327584, 47534, '<td valign="top">hehehehehe  I love it!!!!!!!!!!!!!!!</td>', 'hehehehehe  I love it!!!!!!!!!!!!!!!', '2006-05-09 11:22:20.000000', NULL, 1),
(2396813, 327179, 47534, '<td valign="top">Simple, emotive, powerful.  Not too original but, then again, that wasn''t really the POINT was it?!?  <br/> <br/>I enjoyed it.</td>', 'Simple, emotive, powerful.  Not too original but, then again, that wasn''t really the POINT was it?!?   I enjoyed it.', '2006-05-09 11:22:24.000000', NULL, 1),
